package com.bank.ledger;

import java.util.Arrays;
import java.util.logging.*;

public class DedupeDemo {
    private static final Logger log = Logger.getLogger(DedupeDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        LedgerDeduplicator dedup = new LedgerDeduplicator();

        // Sorted transaction IDs with repeats from retried imports
        long[] txnIds = {1001, 1001, 1002, 1003, 1003, 1003, 1004};
        int unique = dedup.dedupe(txnIds);

        log.info(() -> "Unique transaction IDs: " + unique);
        log.info(() -> "Compacted prefix: " + Arrays.toString(Arrays.copyOf(txnIds, unique)));
    }
}

