class LedgerDeduplicator {
    private static final Logger log = Logger.getLogger(LedgerDeduplicator.class.getName());

    // Slow/fast in place. Input MUST be sorted. O(n) time, O(1) space.
    int dedupe(long[] a) {
        if (a.length == 0) {
            log.warning("Empty ledger import");
            return 0;
        }
        int k = 0; // slow pointer: last kept unique index
        for (int i = 1; i < a.length; i++) { // fast pointer scans all
            if (a[i] != a[k]) {        // new unique value
                k++;
                a[k] = a[i];           // write it into the fresh slot
                log.fine(() -> "Kept unique id at slot " + k);
            }
        }
        return k + 1; // logical length of unique prefix
    }
}

